            &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#L&#233;chelle_de_strat&#233;gie_0&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;L&#39;&#233;chelle de strat&#233;gie&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#ATTAQUERETSUBIRDESDEGATS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;Attaquer et subir des d&#233;g&#226;ts&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;Les conditions du champ de bataille&lt;/a&gt;&lt;/li&gt;
